"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

P1 v0.4 L2 (late fusion) and the attribution controls T, T0, T0-single (plan 6.2, 6.3); trained alike.

Feature groups per decision point (all from before the point):
  audio  (L2 only): the detector's window embedding (fc1 mean and max over the 8 s window, 4096) and the official
         VoxTurn's five answers (13 probabilities, p1v4_voxturn.py);
  det    (L2, T): detector class scores: window maximum, last 3 s maximum, maximum over the 3 s before the line
         starts (7 each); per class the time since its last detection with peak >= 0.5 (log1p seconds) and a "never"
         flag (history detections, p1v4_feats.py); user lines (by speaker tag) since the last attention sound
         (phone, doorbell, knock) with peak >= 0.5;
  text   (L2, T, T0): the history (the situation text's earlier part, newest first; variant full for L2 and T, without
         detector lines for T0) as an all-MiniLM-L6-v2 embedding; the assistant: talking, log1p seconds talking or
         silent, has spoken, its current or last sentence's embedding; speaker tags: number of earlier segments, share
         not the user, the previous segment not the user; the previous point's answer (gold history): S stop /
         continue / none, R respond / not / none;
  line   (all four): the line's Whisper-small transcript embedding, log1p word count, speaker tag and cosine score,
         has a line.
Systems: L2 = audio + det + text + line; T = det + text + line; T0 = text (no detector content) + line;
T0-single = line.
Model: standardised features; logistic regression or a two-layer network (256 hidden, GELU, dropout 0.2) with two
outputs (S = stop, R = respond), binary cross-entropy on the labels that are set (R only where defined); weight decay
1e-4 or 1e-2; 10 epochs, batch 256, AdamW lr 1e-3; the four configurations compared on dev by the operating-point rule
(p1v4_score.operating_point).
usage: python -X utf8 scripts/p1v4_l2.py features train|dev          (needs feats, window detector outputs, VoxTurn)
       python -X utf8 scripts/p1v4_l2.py train l2|t|t0|t0single <out_dir>
"""
import itertools
import json
import math
import os
import sys

import numpy as np
import torch
import torch.nn as nn
import torch.nn.functional as F

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import p1v4_b1 as B1  # noqa: E402
import p1v4_context as C  # noqa: E402
import p1v4_data as D  # noqa: E402
import p1v4_score as S  # noqa: E402
from step0_check_batches import norm  # noqa: E402

FEATS = "data/p1v4/feats"
SYSTEMS = {"l2": ("audio", "det", "text", "line"), "t": ("det", "text", "line"), "t0": ("text0", "line"),
           "t0single": ("line",)}
ATTN = ("phone", "doorbell", "knock")


def history_text(text):
    """The situation text's earlier part, newest first (MiniLM keeps the start, so the most recent lines)."""
    lines = text.split("\n")
    if "Earlier, oldest first:" not in lines:
        return "nothing earlier"
    i = lines.index("Earlier, oldest first:")
    j = next((k for k in range(i + 1, len(lines)) if lines[k].startswith(("Just now", "Nobody has just"))),
             len(lines))
    return " | ".join(reversed(lines[i + 1:j])) or "nothing earlier"


def features(which):
    D.gpu_guard()
    wins, rows = D.load_windows(which)
    ctx = C.Context(which)
    ids = json.load(open(f"{FEATS}/sed_win_{which}_ids.json"))
    pos = {k: i for i, k in enumerate(ids)}
    frames = np.load(f"{FEATS}/sed_win_{which}_frames.npy", mmap_mode="r")
    emb = np.load(f"{FEATS}/sed_win_{which}_emb.npy", mmap_mode="r")
    vt = json.load(open(f"{FEATS}/voxturn_{which}.json"))
    blocks = {k: [] for k in ("audio", "det", "text", "text0", "line")}
    line_t, hist_t, hist0_t, asst_t = [], [], [], []
    for w in wins:
        r = rows[w["key"]]
        k = w["k"]
        p = r["points"][k]
        t = p["t"]
        tr, sc, tags, snd = ctx.point(r, k)
        full, _ = ctx.situation(r, k, "full")
        nos, _ = ctx.situation(r, k, "no_sounds")
        src = {s["id"]: s for s in r["sources"]}
        line = p.get("line")
        ls = src[line]["start"] if line else t
        # audio
        f = np.asarray(frames[pos[w["id"]]], dtype=np.float32)
        blocks["audio"].append(np.concatenate([np.asarray(emb[pos[w["id"]]], dtype=np.float32),
                                               np.asarray(vt[w["id"]], dtype=np.float32)]))
        # det
        w0 = t - D.WIN_S
        li = int(np.floor((ls - w0) * 100))
        pre = f[max(0, li - 300):li + 1].max(0) if li >= 0 else np.zeros(len(D.DET_CLASSES), np.float32)
        since, never = [], []
        for c in D.DET_CLASSES:
            ends = [s[2] for s in snd if s[0] == c and s[3] >= 0.5 and s[1] < t]
            since.append(math.log1p(max(0.0, t - max(ends))) if ends else 0.0)
            never.append(0.0 if ends else 1.0)
        attn = [s[1] for s in snd if s[0] in ATTN and s[3] >= 0.5]
        n_user_since = sum(1 for s in r["sources"] if s["kind"] == "speech" and s["end"] <= t and attn
                           and s["start"] >= max(attn) and tags.get(s["id"]) == "user" and s["id"] in tr)
        blocks["det"].append(np.concatenate([f.max(0), f[-300:].max(0), pre, since, never,
                                             [math.log1p(n_user_since)]]).astype(np.float32))
        # text (history, assistant, tags, previous answer)
        talking = [a for a in r["assistant"] if a["start"] <= t - 1e-3 < a["end"]]
        done = [a for a in r["assistant"] if a["end"] <= t]
        if talking:
            a_state = [1.0, math.log1p(t - talking[0]["start"]), 1.0]
            asst_t.append(talking[0]["text"])
        elif done:
            a_state = [0.0, math.log1p(t - done[-1]["end"]), 1.0]
            asst_t.append(done[-1]["text"])
        else:
            a_state = [0.0, 0.0, 0.0]
            asst_t.append("nothing yet")
        hist = [key for key in tr if key != line]
        n_other = sum(1 for key in hist if tags.get(key) != "user")
        prev_seg = max((src[key.split("@")[0]] for key in hist), key=lambda s: s["start"], default=None)
        prev_other = 1.0 if prev_seg is not None and tags.get(prev_seg["id"], tags.get(f"{prev_seg['id']}@{k}")) \
            != "user" else 0.0
        order = sorted(r["points"], key=lambda q: q["t"])
        i = order.index(p)
        pg = order[i - 1]["gold"] if i else {}
        prev_ans = [pg.get("S") == "stop", pg.get("S") == "continue", pg.get("S") is None,
                    pg.get("R") == "respond", pg.get("R") == "not", pg.get("R") is None]
        tx = np.array(a_state + [math.log1p(len(hist)), n_other / max(1, len(hist)), prev_other]
                      + [float(x) for x in prev_ans], np.float32)
        blocks["text"].append(tx)
        blocks["text0"].append(tx)
        hist_t.append(history_text(full))
        hist0_t.append(history_text(nos))
        # line
        text = tr.get(line, "") if line else ""
        line_t.append(text if line else "nothing said")
        blocks["line"].append(np.array([math.log1p(len(norm(text).split())), 1.0 if tags.get(line) == "user" else 0.0,
                                        sc.get(line, 0.0), 1.0 if line else 0.0], np.float32))
    le = B1.sentence_embeddings(line_t)
    he = B1.sentence_embeddings(hist_t)
    h0 = B1.sentence_embeddings(hist0_t)
    ae = B1.sentence_embeddings(asst_t)
    out = {"audio": np.stack(blocks["audio"]), "det": np.stack(blocks["det"]),
           "text": np.concatenate([np.stack(blocks["text"]), he, ae], 1),
           "text0": np.concatenate([np.stack(blocks["text0"]), h0, ae], 1),
           "line": np.concatenate([np.stack(blocks["line"]), le], 1)}
    for k, v in out.items():
        np.save(f"{FEATS}/l2_{which}_{k}.npy", v.astype(np.float32))
    json.dump([w["id"] for w in wins], open(f"{FEATS}/l2_{which}_ids.json", "w"))
    print(which, {k: v.shape for k, v in out.items()})


def load_X(which, system):
    ids = json.load(open(f"{FEATS}/l2_{which}_ids.json"))
    X = np.concatenate([np.load(f"{FEATS}/l2_{which}_{g}.npy") for g in SYSTEMS[system]], 1)
    return ids, X


def labels(which):
    wins, rows = D.load_windows(which)
    y = np.full((len(wins), 2), -1.0, np.float32)
    for i, w in enumerate(wins):
        if w["gold"].get("S") is not None:
            y[i, 0] = float(w["gold"]["S"] == "stop")
        if w["gold"].get("R") is not None:
            y[i, 1] = float(w["gold"]["R"] == "respond")
    return wins, rows, y


def fit(Xtr, ytr, kind, wd, epochs=10, seed=0, device="cuda"):
    torch.manual_seed(seed)
    d = Xtr.shape[1]
    net = nn.Linear(d, 2) if kind == "lr" else nn.Sequential(nn.Linear(d, 256), nn.GELU(), nn.Dropout(0.2),
                                                             nn.Linear(256, 2))
    net = net.to(device)
    opt = torch.optim.AdamW(net.parameters(), lr=1e-3, weight_decay=wd)
    X, y = torch.from_numpy(Xtr).to(device), torch.from_numpy(ytr).to(device)
    g = torch.Generator(device=device)
    g.manual_seed(seed)
    for _ in range(epochs):
        net.train()
        perm = torch.randperm(len(X), device=device, generator=g)
        for i in range(0, len(X), 256):
            b = perm[i:i + 256]
            lg, yy = net(X[b]), y[b]
            m = yy >= 0
            loss = F.binary_cross_entropy_with_logits(lg[m], yy[m])
            opt.zero_grad()
            loss.backward()
            opt.step()
    return net.eval()


def scores_of(net, X, ids, device="cuda"):
    with torch.no_grad():
        p = torch.sigmoid(net(torch.from_numpy(X).to(device))).cpu().numpy()
    out = {}
    for pid, (ps, pr) in zip(ids, p):
        u, v, k = pid.split("|")
        out[(u, v, int(k))] = {"S": float(ps), "R": float(pr)}
    return out


def rank(res):
    return (res["floors_met"], res["primary"], res["lowest_floor"])


def train(system, out_dir, device="cuda"):
    os.makedirs(out_dir, exist_ok=True)
    D.gpu_guard()
    tr_wins, _, ytr = labels("train")
    dv_wins, dv_rows, _ = labels("dev")
    tr_ids, Xtr = load_X("train", system)
    dv_ids, Xdv = load_X("dev", system)
    assert tr_ids == [w["id"] for w in tr_wins] and dv_ids == [w["id"] for w in dv_wins]
    mu, sd = Xtr.mean(0), Xtr.std(0) + 1e-6
    Xtr, Xdv = (Xtr - mu) / sd, (Xdv - mu) / sd
    keep = (ytr >= 0).any(1)
    log, best = [], None
    for kind, wd in itertools.product(("lr", "mlp"), (1e-4, 1e-2)):
        net = fit(Xtr[keep], ytr[keep], kind, wd, device=device)
        sc = scores_of(net, Xdv, dv_ids, device)
        res = S.operating_point(list(dv_rows.values()), sc)
        res.update(model=kind, weight_decay=wd)
        log.append(res)
        print(json.dumps(res), flush=True)
        if best is None or rank(res) > rank(best):
            best = res
            torch.save({"state": net.state_dict(), "kind": kind, "wd": wd, "mu": mu, "sd": sd, "system": system},
                       os.path.join(out_dir, f"{system}.pt"))
            json.dump({"|".join(map(str, k)): v for k, v in sc.items()},
                      open(os.path.join(out_dir, "scores_dev.json"), "w"))
    json.dump(log, open(os.path.join(out_dir, "train_log.json"), "w"), indent=1)
    print(system, "kept", best["model"], best["weight_decay"], json.dumps(best))


if __name__ == "__main__":
    if sys.argv[1] == "features":
        features(sys.argv[2])
    elif sys.argv[1] == "train":
        train(sys.argv[2], sys.argv[3])
    else:
        raise SystemExit(__doc__)
